    User=apps.get_model('accounts','User')
    alias=schema_editor.connection.alias
    roles={'labor':'PERSONNEL_CATALOG_MANAGER','equipment':'EQUIPMENT_CATALOG_MANAGER'}
    reviewers={}
    rows=Request.objects.using(alias).filter(status='PENDING').select_related('brigade','equipment_type','version','schedule','created_by__role')
    for proposal in rows.iterator():
        role=roles[proposal.kind]
        pair=(proposal.company_id,role)
        if pair not in reviewers:
            reviewers[pair]=list(User.objects.using(alias).filter(company_id=proposal.company_id,is_active=True,role__code=role).order_by('pk')[:2])
        people=reviewers[pair]
        fallback=None
        if not people:
            author=proposal.created_by
            admin=author.is_superuser or author.role_id and author.role.code=='ADMIN'
            fallback=author if author.is_active and author.company_id==proposal.company_id and admin else User.objects.using(alias).filter(company_id=proposal.company_id,is_active=True).filter(Q(role__code='ADMIN')|Q(is_superuser=True)).order_by('pk').first()
        resource=proposal.brigade if proposal.kind=='labor' else proposal.equipment_type
        owner=proposal.version if proposal.version_id else proposal.schedule if proposal.schedule_id else None
        label='должность' if proposal.kind=='labor' else 'технику для планирования'
        task,created=Task.objects.using(alias).get_or_create(company_id=proposal.company_id,key=f'catalogue-review:{proposal.pk}',defaults={
            'catalogue_request_id':proposal.pk,'kind':'CATALOGUE','title':('Проверить новую '+label+': '+resource.name)[:255],
            'description':'Рассмотрите новую позицию в карточке заявки.\n'+proposal.origin_label,
            'target_role':role,'assigned_to_id':people[0].pk if len(people)==1 else fallback.pk if fallback else None,
            'created_by_id':proposal.created_by_id,'construction_object_id':owner.construction_object_id if owner else None,
            'due_date':timezone.localdate(proposal.created_at)+timedelta(days=1)})
        if created:
            Event.objects.using(alias).create(company_id=proposal.company_id,task_id=task.pk,actor_name='Система',action='Создано',text='Восстановлено задание существующей заявки справочника.')


